// Run: npx vite-node scripts/gen-riviera-palettes.ts
import { writeFileSync } from "node:fs";
import { PALETTE_PRESETS } from "../src/features/settings/lib/palette-presets";
import { contrastFailures, paletteCss } from "../src/features/settings/lib/palette-tokens";

let fails = 0;
const out = [
  "/* Generated by scripts/gen-riviera-palettes.ts from src/features/settings/lib/palette-presets.ts. Do not edit by hand.\n   Neutral is the default. Light/dark follows data-riviera-theme, the palette follows data-palette on <html>. */\n",
];
for (const [id, set] of Object.entries(PALETTE_PRESETS)) {
  for (const mode of ["light", "dark"] as const) {
    for (const f of contrastFailures(set[mode])) { console.log(id, mode, f); fails++; }
  }
  out.push(paletteCss(id, set, { isDefault: id === "neutral" }));
}
out.push("/* The page itself paints the palette, so nothing flashes between streamed chunks and hydration. */\n:root body {\n  background: var(--paper);\n  color: var(--ink);\n}\n");
console.log("fails", fails);
if (fails) process.exit(1);
writeFileSync("src/shared/style/riviera-palettes.css", out.join("\n"));
